import React from 'react';

interface ControlValues {
    outer: boolean;
    onlySuggestions: boolean;
    success: boolean;
    warning: boolean;
}

const Controls: React.FC<{ values: ControlValues; onChange: (values: ControlValues) => void }> = ({ values, onChange }) => {
    const handleChange = (key: keyof ControlValues, value: boolean) => {
        onChange({ ...values, [key]: value });
    };

    return (
        <div style={{ display: 'flex', justifyContent: 'center', gap: '20px' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <input
                    type="checkbox"
                    checked={values.outer}
                    onChange={(e) => handleChange('outer', e.target.checked)}
                />
                Outer?
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <input
                    type="checkbox"
                    checked={values.onlySuggestions}
                    onChange={(e) => handleChange('onlySuggestions', e.target.checked)}
                />
                OnlySuggestions?
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <input
                    type="checkbox"
                    checked={values.success}
                    onChange={(e) => handleChange('success', e.target.checked)}
                />
                Success?
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <input
                    type="checkbox"
                    checked={values.warning}
                    onChange={(e) => handleChange('warning', e.target.checked)}
                />
                Warning?
            </label>
        </div>
    );
};

export default Controls;
